// Keep the final position visible for the shared confetti sequence.
const boardBaseRender=labRender;labRender=function(){if(game.lesson.subject!=='board-games'||!BOARD_GRADES[game.lesson.format])return boardBaseRender();const s=game.session,c=s.config;if(game.done){$('#arena').innerHTML='<section class="board-result"><h2>'+esc(s.message||'Match complete!')+'</h2><p>Ready for a rematch? Try swapping who goes first.</p><div class="result-actions"><button class="button primary" data-replay>Play again</button><button class="button secondary" data-edit-result>Edit game</button></div></section>';return;}
 $('#play-title').textContent=game.lesson.title;$('#play-subtitle').textContent='Two players · take turns · any subject';$('#scoreboard').innerHTML='<div class="board-players">'+[0,1].map(i=>'<span class="'+(i===s.data.turn?'active':'')+'" style="--side:'+(c.engine==='boardplay'?BOARD_COLORS[i]:LAB_COLORS[i])+'">'+esc(labPlayer(i))+'</span>').join('')+'</div>';$('.player-bottom>span').textContent='Plan a move. Give your partner a turn.';$('#arena').classList.add('activity-arena');$('#arena').innerHTML='<section class="lab-game board-game" data-lab-engine="'+c.engine+'" data-board-variant="'+c.variant+'">'+LAB_ENGINES[c.engine].render(s.data,c)+'<p class="lab-status" role="status">'+esc(s.message)+'</p>'+'</section>';requestAnimationFrame(()=>requestAnimationFrame(()=>{labFitBoard();boardFit();}));if(s.phase==='feedback'){game.done=true;renderGame();}}
const boardBaseAction=labHandle;labHandle=function(button){if(game?.lesson.subject==='board-games'&&game.session?.phase==='play')game.session.message='';boardBaseAction(button);};
document.addEventListener('DOMContentLoaded',()=>{const q=new URLSearchParams(location.search);if(q.get('subject')==='board-games'&&!q.has('game')){ui.subject='board-games';ui.grade='all';renderLibrary();}});
function boardFit(){if(innerWidth<1024||ui.view!=='player'||game?.lesson.subject!=='board-games')return;const a=$('#arena'),visual=a.querySelector('.board-meadow,.board-dots,.board-flip');if(!visual)return;for(let i=0;i<3;i++){const over=a.scrollHeight-a.clientHeight;if(over<3)break;visual.style.width=Math.max(220,visual.getBoundingClientRect().width-over-8)+'px';}}
window.addEventListener('resize',()=>requestAnimationFrame(boardFit));
// A board game needs player names, not a lesson question bank.
const boardModeEditor=setupModeEditor;setupModeEditor=function(){boardModeEditor();if(draft?.subject==='board-games'&&BOARD_GRADES[draft.format]){const note=$('#mode-setup .mode-explainer');if(note){note.querySelector('p').textContent='One shared board. Two players take turns. No subject questions needed.';note.querySelector('small').textContent='Suggested grades '+BOARD_GRADES[draft.format].join('–')+' · Name both players below, then play.';}}};
const boardRows=renderActivityRows;renderActivityRows=function(){boardRows();if(draft?.subject==='board-games'&&BOARD_GRADES[draft.format])$('#question-rows').closest('.panel').hidden=true;};
const boardClassicInit=LAB_ENGINES.classics.init;LAB_ENGINES.classics.init=function(c,seed){return boardClassicInit(c,c.variant==='tic'&&game?.lesson.subject==='board-games'?(game.lesson.grade>=8?3:2):seed);};
